function joinUrl(baseUrl, ...paths) {
  const url = new URL(baseUrl);
  const basePath = url.pathname.replace(/\/+$/, '');
  const segments = paths
    .map((value) => String(value || '').replace(/^\/+|\/+$/g, ''))
    .filter(Boolean);

  url.pathname = [basePath, ...segments].filter(Boolean).join('/') || '/';
  return url.toString();
